(()=>{
const REFRESH=15*60*1000,AQ_SOURCES=["/weather/air-quality.json","https://raw.githubusercontent.com/kenzuko/Jotrip-Lab/data-weather/data/weather-aqi/latest.json"],POINT_NAMES={an_thoi:"An Thới",duong_dong:"Dương Đông",ganh_dau:"Gành Dầu",rach_gia:"Rạch Giá"},CATEGORIES={GOOD:["Tốt","good"],MODERATE:["Trung bình","moderate"],UNHEALTHY_FOR_SENSITIVE_GROUPS:["Không tốt cho nhóm nhạy cảm","sensitive"],UNHEALTHY:["Không tốt","unhealthy"],VERY_UNHEALTHY:["Rất không tốt","very-unhealthy"],HAZARDOUS:["Nguy hại","hazardous"]};
let aq={status:"UNAVAILABLE",points:{},sampled_time:null,detail:"Chưa có dữ liệu chất lượng không khí"};
const $=id=>document.getElementById(id),num=v=>v===null||v===undefined||v===""||Number.isNaN(Number(v))?null:Number(v),fmt=(v,d=1)=>{v=num(v);return v===null?"—":Number(v.toFixed(d)).toString()};
function ageLabel(value){const t=Date.parse(value||"");if(!Number.isFinite(t))return "chưa có thời gian quan sát";const h=Math.max(0,(Date.now()-t)/3600000);return h<1?`${Math.round(h*60)} phút trước`:h<24?`${Math.round(h)} giờ trước`:`${Math.round(h/24)} ngày trước`}
function category(value){return CATEGORIES[value]||["Chưa xác định","unknown"]}
function panel(){if($("airQualityPanel"))return;const host=document.createElement("section");host.id="airQualityPanel";host.className="panel air-quality-panel";host.innerHTML=`<div class="panel-head premium-head"><div><small>CHẤT LƯỢNG KHÔNG KHÍ</small><h2>AQI & bụi mịn</h2></div><span id="aqiKicker" class="section-kicker">ƯU TIÊN QUAN SÁT</span></div><div class="air-quality-grid"><div class="aqi-focus"><div class="aqi-orb unknown" id="aqiOrb"><span>US AQI</span><b id="aqiValue">—</b><small id="aqiCategory">Chưa có dữ liệu</small></div><p id="aqiStatus">Đang đọc dữ liệu chất lượng không khí…</p></div><div class="air-quality-metrics"><div><span>PM2.5</span><b id="pm25Value">—</b><small>µg/m³ · CAMS</small></div><div><span>PM10</span><b id="pm10Value">—</b><small>µg/m³ · CAMS</small></div><div><span>AQI từ CAMS</span><b id="aqiModelRef">—</b><small>mốc tham chiếu từ mô hình</small></div><div><span>Chênh lệch giữa hai nguồn</span><b id="aqiDivergence">—</b><small>IQAir - CAMS</small></div></div></div><div class="air-quality-foot"><span id="aqiSource">Đang chọn nguồn phù hợp nhất</span><span id="aqiNote">AQI chỉ để theo dõi không khí, không tham gia quyết định vận hành biển.</span></div>`;document.querySelector(".conditions")?.insertAdjacentElement("afterend",host)}
function renderAQ(){panel();const p=aq?.points?.[currentPoint]||{},ready=aq?.status==="POINT_NUMERIC_READY"&&num(p.aqi_us)!==null,[label,cls]=category(p.category),orb=$("aqiOrb"),age=p.sampled_time||aq.sampled_time,isIq=p.aqi_source==="IQAIR_COMMUNITY_REALTIME";if(orb)orb.className=`aqi-orb ${ready?cls:"unknown"}`;$("aqiValue").textContent=ready?String(Math.round(Number(p.aqi_us))):"—";$("aqiCategory").textContent=ready?label:"Chưa có dữ liệu";$("pm25Value").textContent=fmt(p.pm25_ugm3,1);$("pm10Value").textContent=fmt(p.pm10_ugm3,1);$("aqiModelRef").textContent=fmt(p.model_aqi_us,0);const div=num(p.source_divergence_aqi);$("aqiDivergence").textContent=div===null?"—":`${div>0?"+":""}${fmt(div,0)}`;$("aqiStatus").textContent=ready?`${POINT_NAMES[currentPoint]||"Điểm đang xem"} · ${label}`:(aq?.detail||"Dữ liệu AQI chưa sẵn sàng");$("aqiKicker").textContent=isIq?"IQAIR · THỜI GIAN THỰC":"CAMS · MÔ HÌNH";$("aqiSource").textContent=isIq?`IQAir thời gian thực ${p.iqair_city?`· ${p.iqair_city}`:""} · cập nhật ${ageLabel(age)}`:`Phân tích mô hình CAMS · lưới ${aq?.grid_resolution||"0.4°"} · cập nhật ${ageLabel(age)}`;$("aqiNote").textContent=isIq?`AQI chính lấy từ IQAir theo thành phố/điểm gần nhất; PM2.5, PM10 và AQI CAMS là lớp tham chiếu mô hình. ${div!==null&&Math.abs(div)>=20?"Hai nguồn đang lệch đáng kể - nên ưu tiên nguồn thời gian thực và tiếp tục theo dõi.":""}`:`IQAir thời gian thực chưa sẵn sàng ở lần cập nhật này - đang dùng CAMS làm nguồn dự phòng. AQI không tham gia quyết định vận hành biển.`;document.body.dataset.aqi=ready?cls:"unknown";document.body.dataset.aqiSource=isIq?"iqair":"cams"}
async function loadAQ(){let last=null;for(const url of AQ_SOURCES){try{const sep=url.includes("?")?"&":"?",r=await fetch(`${url}${sep}t=${Date.now()}`,{cache:"no-store"});if(!r.ok)throw new Error(`${url} HTTP ${r.status}`);const data=await r.json();if(data?.status!=="POINT_NUMERIC_READY"||!data?.points)throw new Error(`${url} có cấu trúc dữ liệu AQI không hợp lệ`);aq={...aq,...data,points:data.points};renderAQ();return}catch(e){last=e}}aq={...aq,status:"UNAVAILABLE",detail:`Không tải được dữ liệu AQI: ${last?.message||"không rõ nguyên nhân"}`};renderAQ()}
function install(){panel();const prevPoint=renderPoint;renderPoint=function(){prevPoint();renderAQ()};loadAQ();setInterval(loadAQ,REFRESH);document.querySelectorAll(".point-tabs button").forEach(btn=>btn.addEventListener("click",()=>setTimeout(renderAQ,0)))}
window.WeatherLabAirQuality={install,render:renderAQ,load:loadAQ,data:()=>aq};
})();